// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(this));
        vm.deal(address(c), 1 ether);
        Receiver rcvr = new Receiver();
        address payable target = payable(address(rcvr));
        c.withdrawAll(target);
        assertTrue(target.balance == 1 ether);
    }
}

contract Receiver {
    receive() external payable { }
}
